// Method 1: Brute Force
class Solution {
    public int divide(int dividend, int divisor) {
        // Special cases.
        if (dividend == 0) {
            return 0;
        }
        if (divisor == 0 && dividend > 0) {
            return Integer.MAX_VALUE;
        }
        if (divisor == 0 && dividend < 0) {
            return Integer.MIN_VALUE;
        } 
        // Avoid overflow.
        if (dividend == Integer.MIN_VALUE && divisor == -1) {
            return Integer.MAX_VALUE;
        }

        // Convert positives to negatives.
        // Count the negatives to identify the final sign.
        int negativeCnt = 2;
        if (dividend > 0) {
            dividend = -dividend;
            negativeCnt--;
        }

        if (divisor > 0) {
            divisor = -divisor;
            negativeCnt--;
        }

        // Count how many times the divisor can be added.
        int quotient = 0;
        while (dividend <= divisor) {
            dividend -= divisor;
            quotient--;
        }
        // If there's one negative, then the final should be negative.
        // Otherwise, it should be positive.
        if (negativeCnt != 1) {
            quotient = -quotient;
        }
        return quotient;
    }
}
// Time Complexity: O(n)
// Space Complexity: O(1)

